using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
namespace VanderBeer.Api.Models;
public class Categoria { public int Id {get;set;} [Required,StringLength(100)] public string Nome {get;set;}=""; [StringLength(300)] public string? Descricao {get;set;} public bool Ativa {get;set;}=true; public ICollection<Produto> Produtos {get;set;}=[]; }
public class Produto { public int Id {get;set;} [Required,StringLength(150)] public string Nome {get;set;}=""; [StringLength(500)] public string? Descricao {get;set;} [Column(TypeName="decimal(10,2)")] public decimal Preco {get;set;} public int Estoque {get;set;} [StringLength(500)] public string? ImagemUrl {get;set;} public bool Ativo {get;set;}=true; public DateTime DataCadastro {get;set;}=DateTime.UtcNow; public int CategoriaId {get;set;} public Categoria? Categoria {get;set;} public ICollection<ItemPedido> ItensPedido {get;set;}=[]; }
public class Cliente { public Guid Verificador {get;set;}=Guid.NewGuid(); public int Id {get;set;} [Required,StringLength(14)] public string Cpf {get;set;}=""; [Required,StringLength(150)] public string Nome {get;set;}=""; [EmailAddress,StringLength(150)] public string? Email {get;set;} [Required,StringLength(20)] public string Telefone {get;set;}=""; [StringLength(8)] public string? Cep {get;set;} [StringLength(200)] public string? Endereco {get;set;} [StringLength(20)] public string? Numero {get;set;} [StringLength(100)] public string? Bairro {get;set;} [StringLength(100)] public string? Cidade {get;set;} [StringLength(2)] public string? Uf {get;set;} public DateTime DataCadastro {get;set;}=DateTime.UtcNow; public ICollection<Pedido> Pedidos {get;set;}=[]; }
public class Pedido { public int Id {get;set;} public Guid CodigoPedido {get;set;}=Guid.NewGuid(); public int ClienteId {get;set;} public Cliente? Cliente {get;set;} public DateTime DataPedido {get;set;}=DateTime.UtcNow; [Required,StringLength(30)] public string FormaPagamento {get;set;}=""; [Required,StringLength(30)] public string Status {get;set;}="Confirmado"; [Required,StringLength(300)] public string EnderecoEntrega {get;set;}=""; [Column(TypeName="decimal(10,2)")] public decimal Total {get;set;} [Column(TypeName="decimal(10,2)")] public decimal? TrocoPara {get;set;} public bool EstoqueDevolvido {get;set;} public ICollection<ItemPedido> Itens {get;set;}=[]; }
public class ItemPedido { public int Id {get;set;} public int PedidoId {get;set;} public Pedido? Pedido {get;set;} public int ProdutoId {get;set;} public Produto? Produto {get;set;} public int Quantidade {get;set;} [Column(TypeName="decimal(10,2)")] public decimal PrecoUnitario {get;set;} [Column(TypeName="decimal(10,2)")] public decimal Subtotal {get;set;} }
